using System;
using UnityEngine;

/// <summary>
/// How a level is shown outside its scene: map select card, loading card, and HUD track map.
/// Generated by LevelCaptureTool and stored in LevelPresentationCatalog, keyed by LevelInfo.Key.
/// </summary>
[Serializable]
public class LevelPresentation
{
    /// <summary>
    /// LevelInfo.Key of the level.
    /// </summary>
    public string Key;

    /// <summary>
    /// Three-quarter view of the level, 16:9.
    /// </summary>
    public Texture2D Thumbnail;

    /// <summary>
    /// Orthographic view from above, square, north (+z) up.
    /// </summary>
    public Texture2D TopView;

    /// <summary>
    /// World area shown in TopView: x and y are the world x and z of its lower-left corner,
    /// width and height its size in meters.
    /// </summary>
    public Rect TopViewArea;

    /// <summary>
    /// Start, checkpoints, and finish in race order, as positions in TopView from (0, 0) at the
    /// lower left to (1, 1) at the upper right. Empty when the level has no key points.
    /// </summary>
    public Vector2[] Route = new Vector2[0];

    /// <summary>
    /// True when the finish is at the start, so the route is a closed circuit.
    /// </summary>
    public bool IsLoop;

    /// <summary>
    /// Palette of the arena scenery around the shared terrain; levels with their own terrain
    /// have no arena.
    /// </summary>
    public ArenaPalette ArenaPalette = ArenaPalette.Day;

    /// <summary>
    /// The position of a world point in TopView, (0, 0) lower left to (1, 1) upper right.
    /// </summary>
    public Vector2 ToTopView(Vector3 world)
    {
        return new Vector2(
            (world.x - this.TopViewArea.x) / this.TopViewArea.width,
            (world.z - this.TopViewArea.y) / this.TopViewArea.height);
    }
}
